"""Dataset Studio: upload, synthetic, analysis, figures, tables, provenance."""

from __future__ import annotations

from pathlib import Path

import pytest
from httpx import AsyncClient

FIXTURES = Path(__file__).resolve().parents[1] / "fixtures"
SYNTHETIC_LABEL = (
    "Synthetic dataset generated by ResearchForge. "
    "It must not be represented as collected experimental data."
)


def _csrf(client: AsyncClient) -> str:
    token = client.cookies.get("rf_csrf")
    assert token
    return token


async def _register(client: AsyncClient, email: str) -> None:
    response = await client.post(
        "/api/v1/auth/register",
        json={"email": email, "password": "Password123!", "display_name": "Data User"},
    )
    assert response.status_code == 200, response.text


async def _project(client: AsyncClient, title: str = "Dataset Project") -> dict:
    headers = {"X-CSRF-Token": _csrf(client)}
    created = await client.post(
        "/api/v1/projects",
        headers=headers,
        json={"title": title, "status": "active", "research_field": "ML"},
    )
    assert created.status_code == 200, created.text
    return created.json()


@pytest.mark.integration
@pytest.mark.asyncio
async def test_real_upload_profile_and_preview(client: AsyncClient) -> None:
    await _register(client, "dataupload@example.com")
    project = await _project(client)
    headers = {"X-CSRF-Token": _csrf(client)}
    content = (FIXTURES / "sample_dataset.csv").read_bytes()
    uploaded = await client.post(
        f"/api/v1/projects/{project['id']}/datasets/upload",
        headers=headers,
        files={"file": ("sample_dataset.csv", content, "text/csv")},
        data={"name": "Latency study", "provenance_type": "uploaded_real"},
    )
    assert uploaded.status_code == 200, uploaded.text
    body = uploaded.json()
    assert body["provenance_type"] == "uploaded_real"
    assert body["synthetic"] is False
    assert body["version"]["row_count"] == 10
    assert body["version"]["column_count"] == 7
    assert body["version"]["profile"]["preview_rows"]
    assert body["version"]["content_sha256"]
    assert body["version"]["is_immutable_original"] is True


@pytest.mark.integration
@pytest.mark.asyncio
async def test_synthetic_reproducibility_and_locked_label(client: AsyncClient) -> None:
    await _register(client, "synth@example.com")
    project = await _project(client)
    headers = {"X-CSRF-Token": _csrf(client)}
    spec = {
        "name": "Toy synthetic",
        "rows": 40,
        "random_seed": 42,
        "columns": [
            {"name": "x", "type": "float", "min": 0, "max": 1, "distribution": "uniform"},
            {"name": "y", "type": "float", "min": 0, "max": 1, "distribution": "normal"},
            {
                "name": "cls",
                "type": "category",
                "categories": ["pos", "neg"],
            },
        ],
        "class_balance": {"column": "cls", "proportions": {"pos": 0.7, "neg": 0.3}},
        "correlations": [{"a": "x", "b": "y", "r": 0.6}],
    }
    first = await client.post(
        f"/api/v1/projects/{project['id']}/datasets/synthetic",
        headers=headers,
        json=spec,
    )
    assert first.status_code == 200, first.text
    assert first.json()["synthetic"] is True
    assert first.json()["provenance_label"] == SYNTHETIC_LABEL
    assert first.json()["label_locked"] is True
    checksum_a = first.json()["version"]["content_sha256"]

    # same seed -> same checksum
    second = await client.post(
        f"/api/v1/projects/{project['id']}/datasets/synthetic",
        headers=headers,
        json={**spec, "name": "Toy synthetic 2"},
    )
    assert second.status_code == 200
    assert second.json()["version"]["content_sha256"] == checksum_a

    # different seed -> different data
    third = await client.post(
        f"/api/v1/projects/{project['id']}/datasets/synthetic",
        headers=headers,
        json={**spec, "name": "Toy synthetic 3", "random_seed": 99},
    )
    assert third.json()["version"]["content_sha256"] != checksum_a

    locked = await client.patch(
        f"/api/v1/projects/{project['id']}/datasets/{first.json()['id']}/label",
        headers=headers,
        json={"provenance_label": "real experimental data"},
    )
    assert locked.status_code == 422
    assert "cannot be removed" in locked.json()["error"]["message"].lower()


