@pytest.mark.integration
@pytest.mark.asyncio
async def test_analysis_figure_table_export_and_insert(client: AsyncClient) -> None:
    await _register(client, "analysis@example.com")
    project = await _project(client)
    headers = {"X-CSRF-Token": _csrf(client)}
    content = (FIXTURES / "sample_dataset.csv").read_bytes()
    uploaded = await client.post(
        f"/api/v1/projects/{project['id']}/datasets/upload",
        headers=headers,
        files={"file": ("sample_dataset.csv", content, "text/csv")},
    )
    assert uploaded.status_code == 200, uploaded.text
    version_id = uploaded.json()["version"]["id"]

    analysis = await client.post(
        f"/api/v1/projects/{project['id']}/analyses",
        headers=headers,
        json={
            "dataset_version_id": version_id,
            "operation": "t_test",
            "parameters": {"column_a": "latency_ms", "column_b": "batch_size"},
            "random_seed": 7,
        },
    )
    assert analysis.status_code == 200, analysis.text
    assert analysis.json()["status"] == "completed"
    assert analysis.json()["results"]["pvalue"] is not None
    assert analysis.json()["package_versions"]
    assert analysis.json()["code_representation"]
    run_id = analysis.json()["id"]

    # figure without source rejected
    bare = await client.post(
        f"/api/v1/projects/{project['id']}/figures",
        headers=headers,
        json={"kind": "histogram", "title": "No source"},
    )
    assert bare.status_code == 422

    fig = await client.post(
        f"/api/v1/projects/{project['id']}/figures",
        headers=headers,
        json={
            "kind": "histogram",
            "title": "Latency histogram",
            "dataset_version_id": version_id,
            "caption": "Distribution of latency",
            "alt_text": "Histogram of latency_ms",
            "parameters": {"column": "latency_ms"},
        },
    )
    assert fig.status_code == 200, fig.text
    assert fig.json()["storage_png"]
    assert fig.json()["storage_svg"]
    assert fig.json()["storage_pdf"]
    assert fig.json()["source_reference"]

    table = await client.post(
        f"/api/v1/projects/{project['id']}/tables",
        headers=headers,
        json={
            "kind": "statistical_test",
            "title": "T-test results",
            "analysis_run_id": run_id,
        },
    )
    assert table.status_code == 200, table.text
    export = await client.get(
        f"/api/v1/projects/{project['id']}/tables/{table.json()['id']}/export?format=latex"
    )
    assert export.status_code == 200
    assert "tabular" in export.text

    manuscript = await client.get(f"/api/v1/projects/{project['id']}/manuscript")
    section_id = manuscript.json()["sections"][0]["id"]
    inserted = await client.post(
        f"/api/v1/projects/{project['id']}/manuscript-assets/insert",
        headers=headers,
        json={
            "section_id": section_id,
            "asset_type": "figure",
            "asset_stable_id": fig.json()["stable_id"],
        },
    )
    assert inserted.status_code == 200, inserted.text
    assert inserted.json()["cross_ref"].startswith("Fig.")
    refs = await client.get(f"/api/v1/projects/{project['id']}/manuscript-assets")
    assert refs.status_code == 200
    assert refs.json()


@pytest.mark.integration
@pytest.mark.asyncio
async def test_provenance_labels_and_conceptual_separation(client: AsyncClient) -> None:
    await _register(client, "prov@example.com")
    project = await _project(client)
    headers = {"X-CSRF-Token": _csrf(client)}
    synth = await client.post(
        f"/api/v1/projects/{project['id']}/datasets/synthetic",
        headers=headers,
        json={
            "name": "labeled",
            "rows": 20,
            "random_seed": 3,
            "columns": [{"name": "a", "type": "integer", "min": 0, "max": 10}],
        },
    )
    assert SYNTHETIC_LABEL in synth.json()["provenance_label"]
    version_id = synth.json()["version"]["id"]
    fig = await client.post(
        f"/api/v1/projects/{project['id']}/figures",
        headers=headers,
        json={
            "kind": "histogram",
            "title": "Synthetic hist",
            "dataset_version_id": version_id,
            "parameters": {"column": "a"},
        },
    )
    assert SYNTHETIC_LABEL in fig.json()["provenance_label"]

    concept = await client.post(
        f"/api/v1/projects/{project['id']}/figures/conceptual",
        headers=headers,
        json={
            "title": "Architecture",
            "mermaid": "graph LR; A-->B;",
        },
    )
    assert concept.status_code == 200
    assert concept.json()["is_conceptual"] is True
    assert "AI-assisted conceptual illustration" in concept.json()["provenance_label"]


@pytest.mark.integration
@pytest.mark.asyncio
async def test_user_isolation_and_deletion(client: AsyncClient) -> None:
    await _register(client, "ownerdata@example.com")
    project = await _project(client)
    headers = {"X-CSRF-Token": _csrf(client)}
    content = (FIXTURES / "sample_dataset.csv").read_bytes()
    uploaded = await client.post(
        f"/api/v1/projects/{project['id']}/datasets/upload",
        headers=headers,
        files={"file": ("sample_dataset.csv", content, "text/csv")},
    )
    dataset_id = uploaded.json()["id"]

    await client.post("/api/v1/auth/logout", headers=headers)
    await _register(client, "intruderdata@example.com")
    other = {"X-CSRF-Token": _csrf(client)}
    denied = await client.get(
        f"/api/v1/projects/{project['id']}/datasets/{dataset_id}",
        headers=other,
    )
    assert denied.status_code == 404

    await client.post("/api/v1/auth/logout", headers=other)
    login = await client.post(
        "/api/v1/auth/login",
        json={"email": "ownerdata@example.com", "password": "Password123!"},
    )
    assert login.status_code == 200
    owner_headers = {"X-CSRF-Token": _csrf(client)}
    deleted = await client.delete(
        f"/api/v1/projects/{project['id']}/datasets/{dataset_id}",
        headers=owner_headers,
    )
    assert deleted.status_code == 200
    gone = await client.get(
        f"/api/v1/projects/{project['id']}/datasets/{dataset_id}",
        headers=owner_headers,
    )
    assert gone.status_code == 404
